SELECT s.id, s.symbol, s.interval_code, s.decision, s.total_score, s.trend_score, s.volume_score, s.momentum_score, s.latest_price, s.stop_loss, s.take_profit, s.generated_at, LEFT(s.explanation, 400) AS expl_400 FROM crypto_ai.trade_signal s WHERE s.id IN (SELECT signal_id FROM crypto_ai.paper_position WHERE id IN (182,172,162,158,143,137) UNION SELECT exit_signal_id FROM crypto_ai.paper_position WHERE id IN (182,172,162,158,143,137) AND exit_signal_id IS NOT NULL) ORDER BY s.id;